begin;
create or replace function pg_temp.check_true(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'ASSERTION_FAILED: %',label; end if; end $$;
create or replace function pg_temp.expect_error(p_sql text,p_message text) returns void language plpgsql as $$ begin execute p_sql; raise exception 'EXPECTED_ERROR_NOT_RAISED: %',p_message; exception when others then if sqlerrm='EXPECTED_ERROR_NOT_RAISED: '||p_message or position(p_message in sqlerrm)=0 then raise; end if; end $$;
do $$ declare fan uuid:=md5('wave-stage-fixture:1')::uuid; stranger uuid:='92900000-0000-4000-8000-000000000001'; w uuid; c uuid; wb uuid; other uuid; cb uuid; a uuid; state jsonb; replay jsonb; reward jsonb; code text; role_name text;
begin
 select id into w from public.cheer_photocard_collections where campaign_id='c3930f7f-bd2b-4e58-8cec-b3c61f8463fe';
 select id into c from public.cheer_photocard_collections where campaign_id='aedf77a4-52e9-4acd-aa7a-79ceee5ca8eb';
 perform pg_temp.check_true((select count(*)=22 and count(selected_bundle_id)=0 from public.cheer_photocard_entitlements),'prior participants preserved and unclaimed');
 perform pg_temp.check_true(public.read_cheer_photocard_claim(null,w) is null and public.read_cheer_photocard_claim(stranger,w) is null and public.read_cheer_photocard_claim(fan,extensions.gen_random_uuid()) is null,'private claim requires known eligible active owner');
 perform pg_temp.check_true(public.read_cheer_photocard_claim(fan,w)->'ready'='false'::jsonb,'empty configuration not ready');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L)',fan,c),'PHOTOCARD_NOT_READY');
 insert into public.cheer_photocard_bundles(collection_id,title,position) select x.id,'Member '||n,n from public.cheer_photocard_collections x cross join generate_series(0,3) n where x.id in(w,c);
 insert into public.cheer_photocard_assets(collection_id,bundle_id,storage_path,width,height,content_type,position)
 select b.collection_id,b.id,'bundle-test/'||b.id||'/'||n||'.webp',1200,1600,'image/webp',b.position*3+n from public.cheer_photocard_bundles b cross join generate_series(0,2) n where b.collection_id in(w,c) and (b.collection_id=c or n<2);
 select id into wb from public.cheer_photocard_bundles where collection_id=w and position=0;
 select id into other from public.cheer_photocard_bundles where collection_id=w and position=1;
 select id into cb from public.cheer_photocard_bundles where collection_id=c and position=0;
 update public.live_benefit_campaigns set status='draft',published_at=null where id='c3930f7f-bd2b-4e58-8cec-b3c61f8463fe';
 perform pg_temp.check_true(public.read_cheer_photocard_claim(fan,w) is null,'unclaimed disabled campaign hidden');
 update public.live_benefit_campaigns set status='published',published_at=clock_timestamp() where id='c3930f7f-bd2b-4e58-8cec-b3c61f8463fe';
 state:=public.read_cheer_photocard_claim(fan,w);
 perform pg_temp.check_true(state->'ready'='true'::jsonb and jsonb_array_length(state->'options')=4 and state->'assets'='[]'::jsonb and state->'selectedBundleId'='null'::jsonb,'member choices only, no unclaimed asset IDs');
 perform pg_temp.check_true((select array_agg(k order by k)=array['assets','mode','options','ready','selectedBundleId'] from jsonb_object_keys(state) k),'exact claim schema');
 perform pg_temp.check_true(public.read_cheer_photocard_claim(fan,c)->'options'='[]'::jsonb,'random options hidden');
 select id into a from public.cheer_photocard_assets where bundle_id=wb limit 1;
 perform pg_temp.check_true(public.authorize_cheer_photocard_read(fan,a) is null,'guessing unclaimed asset fails');
 update public.cheer_photocard_assets set bundle_id=null where id=a;
 perform pg_temp.check_true(public.read_cheer_photocard_claim(fan,w)->'ready'='false'::jsonb and public.read_cheer_photocard_claim(fan,w)->'options'='[]'::jsonb,'unassigned or incomplete bundles fail closed');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L,%L)',fan,w,wb),'PHOTOCARD_NOT_READY');
 update public.cheer_photocard_assets set bundle_id=wb where id=a;
 perform pg_temp.expect_error(format('update public.cheer_photocard_assets set bundle_id=%L where id=%L',cb,a),'cheer_photocard_asset_bundle_collection_fk');
 insert into public.cheer_photocard_assets(collection_id,bundle_id,storage_path,width,height,content_type,position) values(w,wb,'bundle-test/extra.webp',1200,1600,'image/webp',99);
 perform pg_temp.check_true(public.read_cheer_photocard_claim(fan,w)->'ready'='false'::jsonb,'extra asset fails exact size');
 delete from public.cheer_photocard_assets where collection_id=w and position=99;

 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L)',fan,w),'PHOTOCARD_INVALID_SELECTION');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L,%L)',fan,w,cb),'PHOTOCARD_INVALID_SELECTION');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L,%L)',fan,c,cb),'PHOTOCARD_INVALID_SELECTION');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L,%L)',stranger,w,wb),'PHOTOCARD_NOT_FOUND');
 state:=public.claim_cheer_photocard_bundle(fan,w,wb);
 perform pg_temp.check_true(jsonb_array_length(state->'assets')=2 and state->>'selectedBundleId'=wb::text,'member gets exactly two');
 perform pg_temp.check_true(public.claim_cheer_photocard_bundle(fan,w,wb)=state and public.read_cheer_photocard_claim(fan,w)=state,'retry and lost response recovery stable');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L,%L)',fan,w,other),'PHOTOCARD_ALREADY_CLAIMED');
 update public.live_benefit_campaigns set status='draft',published_at=null where id='c3930f7f-bd2b-4e58-8cec-b3c61f8463fe';
 perform pg_temp.check_true(public.claim_cheer_photocard_bundle(fan,w,wb)=state,'stored rights survive campaign closure');
 update public.live_benefit_campaigns set status='published',published_at=clock_timestamp() where id='c3930f7f-bd2b-4e58-8cec-b3c61f8463fe';
 code:=public.authorize_cheer_photocard_read(fan,a)->>'watermarkCode';
 perform pg_temp.check_true(code ~ '^[A-Z0-9]{12}$' and public.authorize_cheer_photocard_read(fan,a)->>'watermarkCode'=code,'watermark stable');
 perform pg_temp.check_true(not exists(select 1 from public.cheer_photocard_assets x where x.collection_id=w and x.bundle_id<>wb and public.authorize_cheer_photocard_read(fan,x.id) is not null),'other member assets denied');
 state:=public.claim_cheer_photocard_bundle(fan,c);
 perform pg_temp.check_true(jsonb_array_length(state->'assets')=3 and state->'selectedBundleId'<>'null'::jsonb,'random gets three');
 perform pg_temp.check_true(not exists(select 1 from public.cheer_photocard_assets x where x.collection_id=c and x.bundle_id<>(state->>'selectedBundleId')::uuid and public.authorize_cheer_photocard_read(fan,x.id) is not null),'random foreign bundle assets denied');
 for i in 1..10 loop perform pg_temp.check_true(public.claim_cheer_photocard_bundle(fan,c)=state,'no random reroll'); end loop;
 reward:=public.read_celebrity_cheer_event_rewards('changha',fan,'ko')->'event'->'photocard';
 perform pg_temp.check_true((select array_agg(k order by k)=array['assets','collectionId','eligible','title'] from jsonb_object_keys(reward) k) and jsonb_array_length(reward->'assets')=3 and reward::text not like '%storagePath%','legacy read schema private subset');
 -- An unrelated bundle becoming incomplete cannot revoke the stored claim or reroll it.
 delete from public.cheer_photocard_assets where bundle_id in(select id from public.cheer_photocard_bundles where collection_id=c and id<>(state->>'selectedBundleId')::uuid);
 replay:=public.claim_cheer_photocard_bundle(fan,c);
 perform pg_temp.check_true(replay->'ready'='false'::jsonb and replay->'selectedBundleId'=state->'selectedBundleId' and replay->'assets'=state->'assets','existing claim retained after unrelated edits');
 update public.app_users set status='disabled' where id=fan;
 perform pg_temp.check_true(public.read_cheer_photocard_claim(fan,w) is null and public.authorize_cheer_photocard_read(fan,a) is null,'inactive owner denied');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L,%L)',fan,w,wb),'PHOTOCARD_NOT_FOUND');
 update public.app_users set status='active' where id=fan;
 update public.cheer_photocard_collections set distribution_mode='all' where id=w;
 perform pg_temp.check_true(jsonb_array_length(public.read_cheer_photocard_claim(fan,w)->'assets')=8,'legacy all mode unchanged');
 perform pg_temp.expect_error(format('select public.claim_cheer_photocard_bundle(%L,%L)',fan,w),'PHOTOCARD_NOT_READY');
 foreach role_name in array array['anon','authenticated','service_role'] loop
  perform pg_temp.check_true(not has_table_privilege(role_name,'public.cheer_photocard_bundles','select,insert,update,delete'),'no direct bundle access '||role_name);
  perform pg_temp.check_true(has_function_privilege(role_name,'public.claim_cheer_photocard_bundle(uuid,uuid,uuid)','execute')=(role_name='service_role') and has_function_privilege(role_name,'public.read_cheer_photocard_claim(uuid,uuid)','execute')=(role_name='service_role'),'RPC ACL '||role_name);
 end loop;
 perform pg_temp.check_true((select relrowsecurity from pg_class where oid='public.cheer_photocard_bundles'::regclass),'bundles RLS enabled');
end $$;
grant execute on function pg_temp.expect_error(text,text) to anon,authenticated;
set local role anon;
select pg_temp.expect_error('select public.read_cheer_photocard_claim(null,null)','permission denied');
select pg_temp.expect_error('select public.claim_cheer_photocard_bundle(null,null,null)','permission denied');
set local role authenticated;
select pg_temp.expect_error('select public.read_cheer_photocard_claim(null,null)','permission denied');
select pg_temp.expect_error('select public.claim_cheer_photocard_bundle(null,null,null)','permission denied');
reset role;
rollback;
